root<-normalizePath(file.path(dirname(sub("^--file=","",commandArgs(trailingOnly=FALSE)[grepl("^--file=",commandArgs(trailingOnly=FALSE))])),".."),winslash="/");source(file.path(root,"lib/reactome_analysis.R"))
c<-data.frame(source_row=1:3,original_id=c("a","b","c"),uniprot_accession=c("P1","",""),ncbi_gene_id=c("1","2","9"),gene_symbol=c("A","B","C"));u<-data.frame(source_id="P1",Reactome_ID="R-HSA-1",Pathway="One");n<-data.frame(source_id="2",Reactome_ID="R-HSA-2",Pathway="Two");m<-canonical_mapping(c,u,n);stopifnot(sum(m$mapping_status=="mapped")==2,sum(m$mapping_status=="unmapped")==1);f<-reactome_frequency(m,2);stopifnot(nrow(f)==2);e<-reactome_enrichment(m[m$mapping_status=="mapped",],m[m$mapping_status=="mapped",]);stopifnot(all(c("p_value","FDR")%in%names(e)));cat("R Reactome tests passed\n")
